      k.box(width,.023,length,RW.materials.mortar,0,0,0);
      var courses=Math.max(1,Math.ceil(length/(choice==='boardwalk'?.095:.13)));for(var r=0;r<courses;r++)for(var c=0;c<2;c++)k.stone(width*.46,.012,length/courses*.94,m,(c-.5)*width*.49,.016,-length/2+(r+.5)*length/courses,0,0,0,.92+(r%4)*.022);
      for(var side=-1;side<=1;side+=2)k.box(.024,.036,length,RW.materials.pathEdge,side*width/2,.009,0);
      if(choice==='bright')for(var r=0;r<courses;r+=2)k.box(.025,.006,length/courses*.7,RW.materials.pathEdge,0,.025,-length/2+(r+.5)*length/courses);
      if(cfg.id==='neo'||cfg.id==='future')k.box(.009,.006,length,RW.materials.neon,0,.027,0);
